const ENW={};
function ENL(id,t,words,g,dlg,fe,qs){
 const l=EL(id,t,words,[],null,null);const extra=[];
 if(g)extra.push(P(g[0],g[1],{t:"piz",r:g[2],e:g[3]}));
 if(dlg&&dlg.length)extra.push(P("Let's talk: diálogo","Toca cada frase para escucharla y repítela en voz alta.",{t:"en",x:dlg.map(([en,es])=>[en,es,"💬"])}));
 if(fe)extra.push(F(fe[0],fe[1],fe[2]||{t:"emo",x:"🙏"}));
 l.learn.push(...extra);ENW[id]=words.concat(dlg||[]);
 const W=words,pk=(arr,k,not)=>shuf(arr.filter(x=>x!==not)).slice(0,k);
 const t0=pk(W,4).map(([en,es])=>[`¿Qué significa «${en}»?`,es,...pk(W,2,W.find(w=>w[0]===en)).map(w=>w[1])]);
 const t1=pk(W,3).map(([en,es])=>[`¿Cómo se dice «${es}» en inglés?`,en,...pk(W,2,W.find(w=>w[0]===en)).map(w=>w[0])]);
 const D=dlg||[],t2=pk(D,2).map(([en,es])=>[`¿Qué significa «${en}»?`,es,...pk(D.length>2?D:W,2,D.find(w=>w[0]===en)).map(w=>w[1])]).filter(q=>q.length===4&&new Set(q.slice(1)).size===3);
 (qs||[]).forEach((q,i)=>(i%2?t2:t1).push(q));if(t2.length<2)t2.push(...t0.slice(0,2));
 QB[id]=[t0.filter(q=>new Set(q.slice(1)).size===3),t1.filter(q=>new Set(q.slice(1)).size===3),t2];
 l.lv=[[["enw",6,id],["qb",3,id+":0"]],[["enw",5,id],["qb",4,id+":1"]],[["qb",4,id+":2"],["enw",5,id]]];
 return l}
G.enw=id=>{const W=ENW[id]||[];const w=pick(W),k=rnd(0,2),oth=(f)=>shuf(W.filter(x=>x!==w)).slice(0,2).map(f);
 if(k===0)return C(`¿Qué significa «${w[0]}»?`,uniq([w[1],...oth(x=>x[1])]),null,`«${w[0]}» = «${w[1]}».`);
 if(k===1)return C("Escucha y elige lo que oíste.",uniq([w[0],...oth(x=>x[0])]),{t:"listen",w:w[0]},`Se escribe «${w[0]}».`);
 return C(`¿Cómo se dice «${w[1]}» en inglés?`,uniq([w[0],...oth(x=>x[0])]),null,`Se dice «${w[0]}».`)};
