"en19":ENL("en19","What are you doing?",[["reading","leyendo","📖"],["writing","escribiendo","✍️"],["eating","comiendo","🍽️"],["playing","jugando","⚽"],["singing","cantando","🎵"],["dancing","bailando","💃"],["sleeping","durmiendo","😴"],["drawing","dibujando","🎨"],["praying","rezando","🙏"]],["Present continuous","Lo que pasa <b>ahora</b>: am/is/are + verbo-<b>ing</b>. <b>I am reading.</b> <b>She is singing.</b> <b>They are playing.</b>",["I am…","he/she is…","we/they are… + -ing"],["I am drawing.","We are praying."]],[["What are you doing?","¿Qué estás haciendo?"],["I'm doing my homework.","Estoy haciendo mi tarea."],["Can I help you?","¿Te puedo ayudar?"]],["The choir","At Mass the choir <b>is singing</b> and the people <b>are praying</b>.",{t:"emo",x:"🎶 🙏"}],[["«They are playing» significa…","Están jugando","Juegan siempre","Jugaron"],["Con «she» usamos…","is","am","are"]]),
"en20":ENL("en20","There is / There are",[["bed","cama","🛏️"],["table","mesa","🍽️"],["chair","silla","🪑"],["window","ventana","🪟"],["door","puerta","🚪"],["lamp","lámpara","💡"],["sofa","sofá","🛋️"],["picture","cuadro","🖼️"],["crucifix","crucifijo","✝️"]],["There is / There are","<b>There is</b> (singular): There is a lamp. <b>There are</b> (plural): There are two chairs. Pregunta: <b>Is there…? Are there…?</b>",["There is + uno","There are + varios"],["There is a crucifix in my room.","There are three windows."]],[["Is there a garden in your house?","¿Hay un jardín en tu casa?"],["Yes, there is.","Sí, hay."],["There are many flowers.","Hay muchas flores."]],["A prayer corner","In many Catholic homes <b>there is</b> a prayer corner with a cross and a picture of Mary.",{t:"emo",x:"✝️ 🕯️"}],[["Para plural se usa…","There are","There is","There am"],["«Is there a lamp?» significa…","¿Hay una lámpara?","¿Es una lámpara?","¿Dónde está la lámpara?"]]),
"en21":ENL("en21","Possessives: my, your, his, her",[["my","mi","🙋"],["your","tu","👉"],["his","su (de él)","👦"],["her","su (de ella)","👧"],["our","nuestro","👨‍👩‍👧"],["their","su (de ellos)","👥"],["its","su (de una cosa/animal)","🐶"]],["Possessive adjectives","<b>This is my book.</b> <b>Her name is Mary.</b> <b>Our Father…</b>",["my, your, his, her, its, our, their"],["His name is Joseph.","Our church is beautiful."]],[["What's your name?","¿Cómo te llamas?"],["My name is Lucy. What's his name?","Me llamo Lucía. ¿Cómo se llama él?"],["His name is Peter.","Él se llama Pedro."]],["Our Father","Decimos <b>Our</b> Father porque todos somos hermanos.",{t:"emo",x:"👨‍👩‍👧‍👦 🙏"}],[["«Her name is Mary» significa…","Su nombre (de ella) es María","Mi nombre es María","Tu nombre es María"],["«Our» significa…","nuestro","su","mi"]]),
"en22":ENL("en22","At the restaurant",[["menu","menú","📋"],["water","agua","💧"],["soup","sopa","🍲"],["chicken","pollo","🍗"],["rice","arroz","🍚"],["salad","ensalada","🥗"],["juice","jugo","🧃"],["dessert","postre","🍰"],["bill","cuenta","🧾"]],["I would like…","Para pedir con cortesía: <b>I would like</b> (I'd like) a soup, please. <b>Can I have</b> some water, please?",["I'd like…","Can I have…?"],["I'd like chicken and rice, please.","Can I have the bill, please?"]],[["Are you ready to order?","¿Listos para ordenar?"],["Yes. I'd like a salad, please.","Sí, quisiera una ensalada, por favor."],["Anything to drink?","¿Algo de tomar?"],["Water, please. Thank you!","Agua, por favor. ¡Gracias!"]],["Grace","Before eating, even at a restaurant, we can pray quietly: <b>Bless us, O Lord…</b>",{t:"emo",x:"🍽️ 🙏"}],[["«I'd like» significa…","Quisiera","Me gusta","Tengo"],["«the bill» es…","la cuenta","el menú","la propina"]]),
"en23":ENL("en23","At Mass",[["Mass","Misa","⛪"],["priest","sacerdote","✝️"],["altar","altar","🕯️"],["Bible","Biblia","📖"],["Gospel","Evangelio","📜"],["Communion","Comunión","🍞"],["choir","coro","🎶"],["holy water","agua bendita","💧"],["kneel","arrodillarse","🧎"],["sign of peace","saludo de paz","🤝"]],["Mass responses","Priest: <b>The Lord be with you.</b> — All: <b>And with your spirit.</b>",["The Lord be with you","And with your spirit"],["Thanks be to God.","Lord, have mercy."]],[["The Lord be with you.","El Señor esté con ustedes."],["And with your spirit.","Y con tu espíritu."],["Peace be with you.","La paz sea contigo."]],["Lord, have mercy","<b>Lord, have mercy. Christ, have mercy. Lord, have mercy.</b>",{t:"en",x:[["Lord, have mercy","Señor, ten piedad","🙏"],["Thanks be to God","Demos gracias a Dios","🙌"]]}],[["Respuesta a «The Lord be with you»:","And with your spirit","Thanks be to God","Amen only"],["«Communion» significa…","Comunión","Confesión","Confirmación"]]),
"en24":ENL("en24","Jobs",[["teacher","maestro","👩‍🏫"],["doctor","doctor","👩‍⚕️"],["nurse","enfermera","🧑‍⚕️"],["farmer","campesino","👨‍🌾"],["firefighter","bombero","🧑‍🚒"],["police officer","policía","👮"],["cook","cocinero","🧑‍🍳"],["carpenter","carpintero","🪚"],["priest","sacerdote","✝️"],["nun","religiosa","🧕"]],["What does he do?","<b>He is a carpenter.</b> <b>She is a nurse.</b> <b>What do you want to be?</b> — <b>I want to be a doctor.</b>",["He/She is a…","I want to be…"],["My mother is a teacher.","I want to be a farmer."]],[["What do you want to be?","¿Qué quieres ser?"],["I want to be a doctor to help people.","Quiero ser doctor para ayudar a la gente."],["That's great!","¡Qué bien!"]],["Saint Joseph the Worker","St. Joseph was a <b>carpenter</b>. Jesus learned to work with him.",IMG("joseSueno","San José")],[["¿Qué oficio tenía san José?","carpenter","farmer","doctor"],["«I want to be a nurse» significa…","Quiero ser enfermera","Soy enfermera","Fui enfermera"]]),
