"en25":ENL("en25","Present simple: he, she, it",[["works","trabaja","💼"],["plays","juega","⚽"],["goes","va","🚶"],["watches","ve","📺"],["studies","estudia","📚"],["has","tiene","🤲"],["eats","come","🍽️"],["lives","vive","🏠"]],["Third person -s","Con <b>he, she, it</b> el verbo lleva <b>-s</b>: she works, he plays. Terminados en -ch, -sh, -o: <b>-es</b> (watches, goes). Consonante + y: <b>-ies</b> (studies). Irregular: have → <b>has</b>.",["he/she/it + -s","-es","-ies","has"],["My dad works in an office.","Maria studies English."]],[["Where does your mom work?","¿Dónde trabaja tu mamá?"],["She works at a hospital.","Trabaja en un hospital."],["She helps sick people.","Ayuda a la gente enferma."]],["Jesus loves","<b>God loves you.</b> <b>Mary prays for us.</b> ¡Fíjate en la -s!",{t:"emo",x:"❤️"}],[["«She ___ English» (study)","studies","studys","study"],["«He ___ TV» (watch)","watches","watchs","watch"]]),
"en26":ENL("en26","Do you…? Does she…?",[["Do you…?","¿Tú…?","❓"],["Does he…?","¿Él…?","❓"],["Yes, I do","Sí","✅"],["No, I don't","No","❌"],["Yes, she does","Sí (ella)","✅"],["No, he doesn't","No (él)","❌"],["don't","no (I/you/we/they)","🚫"],["doesn't","no (he/she/it)","🚫"]],["Questions and negatives","<b>Do you like pizza?</b> — Yes, I do. <b>Does she play soccer?</b> — No, she doesn't. Con doesn't el verbo va sin -s: She doesn't <b>play</b>.",["Do / Does + sujeto + verbo","don't / doesn't"],["Do you go to Mass on Sunday?","He doesn't eat meat on Good Friday."]],[["Do you go to Mass on Sundays?","¿Vas a Misa los domingos?"],["Yes, I do. I go with my family.","Sí, voy con mi familia."],["Does your brother go too?","¿Tu hermano también va?"],["Yes, he does.","Sí, él también."]],["Sunday","<b>Sunday is the Lord's Day.</b>",{t:"emo",x:"⛪ ☀️"}],[["«Does she ___ soccer?»","play","plays","playing"],["Respuesta negativa con he:","No, he doesn't","No, he don't","No, he isn't"]]),
"en27":ENL("en27","How often? Always, never",[["always","siempre","💯"],["usually","normalmente","🔁"],["often","a menudo","📅"],["sometimes","a veces","🔀"],["rarely","rara vez","🐢"],["never","nunca","🚫"],["every day","todos los días","📆"],["once a week","una vez a la semana","1️⃣"]],["Frequency adverbs","Van antes del verbo: <b>I always pray at night.</b> Después de be: <b>She is never late.</b>",["antes del verbo","después de am/is/are"],["We usually have dinner together.","I never lie."]],[["How often do you read?","¿Con qué frecuencia lees?"],["I read every day.","Leo todos los días."],["Great habit!","¡Gran hábito!"]],["Pray always","St. Paul: <b>«Pray without ceasing»</b> (1 Thes 5, 17).",{t:"emo",x:"🙏 ♾️"}],[["«never» significa…","nunca","siempre","a veces"],["Orden correcto:","I always pray","I pray always night","Always I pray"]]),
"en28":ENL("en28","Hobbies and free time",[["read books","leer libros","📚"],["play video games","jugar videojuegos","🎮"],["ride a bike","andar en bici","🚲"],["play the guitar","tocar la guitarra","🎸"],["paint","pintar","🎨"],["cook","cocinar","🍳"],["go hiking","ir de excursión","🥾"],["watch movies","ver películas","🎬"],["collect stamps","coleccionar timbres","📮"]],["Like + -ing","<b>I like reading.</b> <b>She loves painting.</b> <b>He hates cooking.</b>",["like / love / hate + -ing"],["I love riding my bike.","My sister likes painting."]],[["What do you do in your free time?","¿Qué haces en tu tiempo libre?"],["I like playing the guitar.","Me gusta tocar la guitarra."],["Cool! I like singing.","¡Genial! A mí me gusta cantar."]],["Use your talents","God gives us <b>talents</b>; we use them to serve others.",{t:"emo",x:"🎁 🤲"}],[["«I love painting» significa…","Me encanta pintar","Pinto siempre","Odio pintar"],["Después de «like» va…","verbo con -ing","verbo con -ed","nada"]]),
"en29":ENL("en29","Directions in the city",[["turn left","da vuelta a la izquierda","⬅️"],["turn right","da vuelta a la derecha","➡️"],["go straight","sigue derecho","⬆️"],["corner","esquina","📐"],["street","calle","🛣️"],["block","cuadra","🏘️"],["traffic light","semáforo","🚦"],["crosswalk","paso peatonal","🚸"]],["Giving directions","<b>Go straight two blocks and turn left. The church is on the right.</b>",["Go straight","Turn left/right","It's on the…"],["Turn right at the corner.","Cross at the crosswalk."]],[["Excuse me, how do I get to the church?","Disculpe, ¿cómo llego a la iglesia?"],["Go straight and turn left at the traffic light.","Siga derecho y dé vuelta a la izquierda en el semáforo."],["Thank you! God bless you.","¡Gracias! Dios le bendiga."]],["The Way","Jesus said: <b>«I am the way, the truth and the life»</b> (Jn 14, 6).",{t:"emo",x:"🛣️ ✝️"}],[["«turn right» significa…","da vuelta a la derecha","sigue derecho","da vuelta a la izquierda"],["Dónde se cruza la calle con seguridad:","crosswalk","corner","block"]]),
"en30":ENL("en30","Shopping and money",[["How much…?","¿Cuánto…?","💲"],["cheap","barato","🟢"],["expensive","caro","🔴"],["price","precio","🏷️"],["money","dinero","💵"],["coins","monedas","🪙"],["change","cambio","🔁"],["size","talla","📏"]],["How much is / are?","<b>How much is this shirt?</b> <b>How much are these shoes?</b> this/that (uno), these/those (varios).",["How much is…?","How much are…?","this/these"],["This book is cheap.","Those shoes are expensive."]],[["How much are these apples?","¿Cuánto cuestan estas manzanas?"],["They are twenty pesos a kilo.","Veinte pesos el kilo."],["I'll take two kilos, please.","Me llevo dos kilos, por favor."]],["Honest","Be honest with money: give back the extra <b>change</b>!",{t:"emo",x:"🪙 ✅"}],[["«expensive» significa…","caro","barato","gratis"],["Para varios se usa…","these","this","that"]]),
"en31":ENL("en31","Health: I have a headache",[["headache","dolor de cabeza","🤕"],["stomachache","dolor de estómago","🤢"],["toothache","dolor de muelas","🦷"],["fever","fiebre","🤒"],["cold","resfriado","🤧"],["cough","tos","😷"],["sore throat","dolor de garganta","🗣️"],["medicine","medicina","💊"],["rest","descansar","🛌"]],["What's the matter?","<b>What's the matter?</b> — <b>I have a headache.</b> Consejo: <b>You should rest.</b> <b>You shouldn't eat candy.</b>",["I have a…","You should…"],["You should see a doctor.","You should drink water."]],[["What's the matter?","¿Qué te pasa?"],["I have a fever and a cough.","Tengo fiebre y tos."],["You should stay in bed and rest.","Deberías quedarte en cama y descansar."],["I'll pray for you.","Rezaré por ti."]],["Jesus heals","Jesus healed the sick. We pray: <b>«Lord, heal the sick.»</b>",{t:"emo",x:"🩺 🙏"}],[["«You should rest» significa…","Deberías descansar","Descansa siempre","Descansaste"],["«fever» significa…","fiebre","tos","gripa"]]),
"en32":ENL("en32","Reading: Saint Francis and the animals",[["saint","santo","😇"],["poor","pobre","🤲"],["brother","hermano","👦"],["wolf","lobo","🐺"],["birds","pájaros","🐦"],["peace","paz","🕊️"],["creation","creación","🌍"],["sun","sol","☀️"],["moon","luna","🌙"]],["Reading strategies","Lee el título, mira las imágenes, busca palabras conocidas, adivina por el contexto.",["Título","Imágenes","Palabras clave"],["Francis loved God and all creatures.","He called the sun «Brother Sun»."]],[["Saint Francis was born in Assisi, Italy.","San Francisco nació en Asís, Italia."],["He was rich, but he gave everything to the poor.","Era rico, pero dio todo a los pobres."],["He talked to the birds about God.","Les hablaba a los pájaros de Dios."],["He made peace with a wolf.","Hizo las paces con un lobo."]],["Canticle","<b>«Praised be You, my Lord, through Brother Sun.»</b>",IMG("francisco","San Francisco")],[["¿Dónde nació san Francisco?","Assisi","Rome","Paris"],["«He gave everything to the poor» significa…","Dio todo a los pobres","Era pobre","Tenía todo"]]),
