"en33":ENL("en33","Was and were",[["was","era/estaba (I/he/she/it)","⏪"],["were","eran/estaban (you/we/they)","⏪"],["yesterday","ayer","📅"],["last week","la semana pasada","🗓️"],["ago","hace (tiempo)","⏳"],["born","nacido","👶"]],["Past of be","<b>I was at home yesterday.</b> <b>They were happy.</b> Negativo: wasn't / weren't. Pregunta: <b>Were you at school?</b>",["I/he/she/it was","you/we/they were"],["Jesus was born in Bethlehem.","The apostles were fishermen."]],[["Where were you yesterday?","¿Dónde estabas ayer?"],["I was at my grandma's house.","Estaba en casa de mi abuela."],["Was it fun?","¿Fue divertido?"],["Yes, it was!","¡Sí!"]],["Born in Bethlehem","<b>Jesus was born in Bethlehem.</b> <b>Mary and Joseph were there.</b>",IMG("natividad","Natividad")],[["«They ___ happy»","were","was","is"],["«Jesus was born in Bethlehem» significa…","Jesús nació en Belén","Jesús vive en Belén","Jesús irá a Belén"]]),
"en34":ENL("en34","Past simple: regular verbs",[["played","jugó","⚽"],["walked","caminó","🚶"],["visited","visitó","🏠"],["helped","ayudó","🤝"],["prayed","rezó","🙏"],["cooked","cocinó","🍳"],["studied","estudió","📚"],["stopped","se detuvo","🛑"]],["-ed","Pasado regular: verbo + <b>-ed</b> (played). Terminados en e: +d (lived). Consonante + y: -ied (studied). Consonante-vocal-consonante: se dobla (stopped).",["+ed","+d","-ied","doble consonante"],["We visited our grandparents.","Mary prayed the Rosary."]],[["What did you do last weekend?","¿Qué hiciste el fin de semana?"],["I helped my dad and played soccer.","Ayudé a mi papá y jugué futbol."],["Nice!","¡Qué bien!"]],["Jesus helped","<b>Jesus helped the sick and talked to the children.</b>",{t:"emo",x:"✝️ 🤝"}],[["Pasado de «study»:","studied","studyed","studed"],["Pasado de «stop»:","stopped","stoped","stopt"]]),
"en35":ENL("en35","Past simple: irregular verbs",[["went","fue","🚶"],["ate","comió","🍽️"],["saw","vio","👀"],["had","tuvo","🤲"],["came","vino","🏃"],["made","hizo","🛠️"],["gave","dio","🎁"],["said","dijo","💬"],["took","tomó","✋"],["rose","resucitó / se levantó","🌅"]],["Irregular verbs","No llevan -ed; hay que aprenderlos: go→<b>went</b>, eat→<b>ate</b>, see→<b>saw</b>, have→<b>had</b>, give→<b>gave</b>, rise→<b>rose</b>.",["go-went","see-saw","give-gave"],["I went to Mass on Sunday.","Jesus rose from the dead."]],[["Did you see the procession?","¿Viste la procesión?"],["Yes! I saw it with my family.","¡Sí! La vi con mi familia."],["We went to church after.","Después fuimos a la iglesia."]],["He is risen!","<b>Jesus rose from the dead on the third day.</b> Alleluia!",IMG("resurreccion","Resurrección")],[["Pasado de «go»:","went","goed","gone"],["«Jesus rose» significa…","Jesús resucitó","Jesús nació","Jesús comió"]]),
"en36":ENL("en36","Did you…? Questions in the past",[["Did you…?","¿Tú … (pasado)?","❓"],["didn't","no (pasado)","🚫"],["Where did…?","¿Dónde…?","📍"],["What did…?","¿Qué…?","❔"],["When did…?","¿Cuándo…?","🕐"],["Why did…?","¿Por qué…?","🤔"]],["Did + verbo base","<b>Did you go?</b> (no «did you went»). Negativo: <b>I didn't go.</b> Respuestas: Yes, I did. / No, I didn't.",["Did + sujeto + verbo base","didn't + verbo base"],["Where did you go?","I didn't watch TV."]],[["Did you do your homework?","¿Hiciste tu tarea?"],["Yes, I did. And I read a book.","Sí. Y leí un libro."],["What book did you read?","¿Qué libro leíste?"],["A book about Saint Patrick.","Uno sobre san Patricio."]],["Saint Patrick","St. Patrick used the <b>shamrock</b> to teach the Holy Trinity in Ireland.",{t:"emo",x:"☘️"}],[["Correcto:","Did you go?","Did you went?","Do you went?"],["Negativo correcto:","I didn't eat","I didn't ate","I not ate"]]),
"en37":ENL("en37","Telling a story: first, then",[["first","primero","1️⃣"],["then","luego","➡️"],["next","después","⏭️"],["after that","después de eso","🔜"],["finally","finalmente","🏁"],["once upon a time","había una vez","📖"],["suddenly","de repente","⚡"],["the end","fin","🔚"]],["Sequence words","Ordenan una historia: <b>First</b>, … <b>Then</b>, … <b>Finally</b>, … Con pasado simple.",["first","then","finally"],["First, we prayed. Then, we ate.","Suddenly, it started to rain."]],[["Tell me about your day.","Cuéntame de tu día."],["First, I went to school. Then, I played with my friends.","Primero fui a la escuela. Luego jugué con mis amigos."],["Finally, I prayed and went to bed.","Finalmente recé y me fui a dormir."]],["The Prodigal Son","<b>First</b>, the son left home. <b>Then</b>, he lost everything. <b>Finally</b>, he came back and his father hugged him.",IMG("prodigoM","Hijo pródigo")],[["«suddenly» significa…","de repente","finalmente","primero"],["Palabra para terminar una historia:","finally","first","then"]]),
