"en39":ENL("en39","Comparatives: bigger, more beautiful",[["bigger","más grande","🐘"],["smaller","más pequeño","🐭"],["taller","más alto","🦒"],["faster","más rápido","🐆"],["better","mejor","👍"],["worse","peor","👎"],["more beautiful","más hermoso","🌸"],["more important","más importante","⭐"]],["Comparatives","Palabras cortas: <b>-er + than</b> (taller than). Largas: <b>more … than</b> (more beautiful than). Irregulares: good→<b>better</b>, bad→<b>worse</b>.",["-er than","more … than","better / worse"],["An elephant is bigger than a mouse.","Love is more important than money."]],[["Who is taller, you or your brother?","¿Quién es más alto, tú o tu hermano?"],["My brother is taller than me.","Mi hermano es más alto que yo."],["But I'm faster!","¡Pero yo soy más rápido!"]],["The greatest is love","<b>«Faith, hope and love… the greatest of these is love»</b> (1 Cor 13, 13).",{t:"emo",x:"❤️"}],[["Comparativo de «good»:","better","gooder","more good"],["«more beautiful than» se usa con palabras…","largas","cortas","de una letra"]]),
