"en43":ENL("en43","Rules: must, mustn't, should",[["must","deber (obligación)","❗"],["mustn't","no deber (prohibido)","⛔"],["should","debería (consejo)","💡"],["have to","tener que","📋"],["rules","reglas","📜"],["respect","respeto","🤝"]],["Modal verbs","<b>You must wear a seatbelt.</b> (obligación) <b>You mustn't run in church.</b> (prohibido) <b>You should be kind.</b> (consejo)",["must","mustn't","should + verbo"],["We must respect others.","You should forgive."]],[["What are the rules in your house?","¿Cuáles son las reglas de tu casa?"],["We must say please and thank you.","Debemos decir por favor y gracias."],["And we mustn't fight!","¡Y no debemos pelear!"]],["The Ten Commandments","<b>«You shall not steal. You shall not lie.»</b> God's rules help us to be free.",IMG("moisesR","Moisés")],[["«You mustn't» expresa…","prohibición","consejo","futuro"],["«You should be kind» significa…","Deberías ser amable","Debes ser amable siempre","Fuiste amable"]]),
